ning and it’s ruining me.","We’ve been arguing about this for months.","I run hot and cold on this one.","It rains a lot here, which doesn’t help."],"pairs":[["Luas to campus","Cycle in winter"],["Shower in the morning","Shower at night"],["Dishes straight away","Dishes later"],["Walk to the shop","Order delivery"],["Alarm across the room","Phone by the bed"],["Make the bed","Leave it"],["Early bird","Night owl"],["Tea","Coffee"],["Call","Text"],["Voice notes","Typed messages"],["A paper diary","A phone calendar"],["A to-do list","Just remember"],["Plan the week on Sunday","Wing it"],["Pay by card","Pay in cash"],["Bus","Walk"],["Window open","Window closed"],["Heating on early","Wear a jumper"],["Tidy daily","A big weekend clean"],["Laundry on Sunday","Little and often"],["Cook extra","Order in"],["Leave early","Arrive on the dot"],["Reply to all emails","Batch them"],["Phone on silent","Phone on vibrate"],["Lunch at the desk","Lunch outside"],["Use a shopping list","Browse"],["Stock up on basics","Shop little and often"],["Lights off at 11","Stay up late"],["Podcasts on the commute","Music"],["Morning run","Morning lie-in"],["Take the stairs","Take the lift"],["A weekend away","A weekend at home"],["Charge overnight","Charge during the day"],["Dark mode","Light mode"],["Ask for directions","Use the map app"],["An umbrella","A hood"],["Arrive early","Arrive late"],["Carry a book","Carry earphones"],["Keep receipts","Bin them"],["Clean as you cook","Clean after"],["Fresh bread","Toasted sliced"],["Batch cook on Sundays","Cook daily"],["Wash hair daily","Every other day"],["Say yes to everything","Pick one plan"],["Buy a lottery ticket","Save the €2"],["A newspaper","A news app"],["Share the umbrella","Run for it"],["The window seat","The aisle seat"],["Wait politely","Skip the queue"],["Tip the delivery rider","Don’t"],["Reply to the group chat now","Mute it"],["Take the long way home","Take the quick way"]]},{"n":40,"shape":"Start {a} or {b} this month?","tails":[""],"contexts":["I’m trying to build one habit that actually sticks.","I’ve got about ten minutes a day to spare.","My last three attempts lasted a week each."],"pools":[["Reading daily","A morning walk","Journaling","Cold showers","Meal planning","A weekly call home","Stretching","Learning a language","A gratitude list","A no-phone hour"]]}]}]$topics$::jsonb;
  proper_words text[] := array['Luas','Spotify','Kindle','Airbnb','Parkrun','Dry','Sunday','Friday','Saturday','Monday','January','Irish','Dublin','Netflix','Berkeley','Hamilton','Ussher','Interrail','Pilates','Instant'];
  uids int[];
  t jsonb; s jsonb; rec record; fill text;
  qid int; oa int; ob int; author int; created timestamptz; closes timestamptz;
  nvoters int; share numeric; label text; a_ids int[]; ta text; tb text; shape text; is_proper boolean;
begin
  if exists (select 1 from public.users where email like '%@seed.thisorthat.invalid') then
    raise exception 'sample content already present';
  end if;

  -- ~220 fictional people with unique usernames like niamh.kelly
  create temp table _people on commit drop as
  select distinct on (lower(f || '.' || l)) f, l, lower(regexp_replace(f || '.' || l, '[^A-Za-z.]', '', 'g')) as username
  from (select f, l from unnest(firsts) f cross join unnest(lasts) l order by random() limit 260) x
  order by lower(f || '.' || l), random();
  delete from _people where username in (select username from _people group by username having count(*) > 1) and false;
  create temp table _picked on commit drop as select * from _people order by random() limit 220;

  with ins as (
    insert into public.users (username, email, password_hash, display_name, region, bio)
    select p.username, p.username || '@seed.thisorthat.invalid', '$2b$10$NfkZe5X4iN3Cd9iZIRUmA.8yZa8t7UQUmqfEFHs.amst5h4F8/1Mu', p.f || ' ' || p.l,
           regions[1 + floor(random() * array_length(regions, 1))::int],
           (array['', '', 'Votes on everything.', 'Here for the arguments.', 'Overthinks small decisions.', 'Coffee first, opinions after.'])[1 + floor(random() * 6)::int]
    from _picked p
    on conflict do nothing
    returning user_id
  )
  select array_agg(user_id) into uids from ins;

  -- 3 or 4 topic interests per person
  insert into public.user_preferences (user_id, category_id)
  select distinct on (u.user_id, c.category_id) u.user_id, c.category_id
  from unnest(uids) as u(user_id)
  cross join lateral (select category_id from public.categories order by random() limit 3 + floor(random() * 2)::int) c
  on conflict do nothing;

  for t in select * from jsonb_array_elements(topics) loop
    for s in select * from jsonb_array_elements(t->'sets') loop
      for rec in
        with cand as (
          select p.a, p.b from (
            select a.v as a, b.v as b
            from jsonb_array_elements(coalesce(s->'pools', '[]'::jsonb)) as pool(arr),
                 lateral jsonb_array_elements_text(pool.arr) with ordinality as a(v, i),
                 lateral jsonb_array_elements_text(pool.arr) with ordinality as b(v, j)
            where a.i < b.j
            union all
            select pr->>0, pr->>1 from jsonb_array_elements(coalesce(s->'pairs', '[]'::jsonb)) as pr
          ) p
        )
        select a, b from cand order by random() limit (s->>'n')::int
      loop
        shape := s->>'shape';
        is_proper := coalesce((s->>'proper')::boolean, false);
        -- options sit in the middle of a sentence: 'A museum' becomes 'a museum', but 'Lisbon' and 'iPhone 16' stay as written
        ta := rec.a; tb := rec.b;
        if not is_proper then
          if left(shape, 3) <> '{a}' and rec.a ~ '^[A-Z][a-z]*( |$)' and split_part(rec.a, ' ', 1) <> all(proper_words) then ta := lower(left(rec.a, 1)) || substr(rec.a, 2); end if;
          if rec.b ~ '^[A-Z][a-z]*( |$)' and split_part(rec.b, ' ', 1) <> all(proper_words) then tb := lower(left(rec.b, 1)) || substr(rec.b, 2); end if;
        end if;
        created := now() - (1 + floor(random() * 330)) * interval '1 hour';
        closes := created + (array[24, 48, 72, 168, 168])[1 + floor(random() * 5)::int] * interval '1 hour';
        if closes < now() and random() < 0.8 then closes := now() + (4 + floor(random() * 150)) * interval '1 hour'; end if;
        author := uids[1 + floor(random() * array_length(uids, 1))::int];

        insert into public.questions (user_id, category_id, title, description, is_anonymous, comments_enabled, hide_results, status, closes_at, created_at)
        values (
          author,
          (select category_id from public.categories where name = t->>'topic'),
          replace(replace(replace(shape, '{a}', ta), '{b}', tb), '{tail}',
                  (s->'tails'->>(floor(random() * jsonb_array_length(s->'tails'))::int))),
          replace(replace(s->'contexts'->>(floor(random() * jsonb_array_length(s->'contexts'))::int), '{a}', ta), '{b}', tb),
          random() < 0.18, true, true, 'open', closes, created)
        returning question_id into qid;

        insert into public.options (question_id, option_text, position) values (qid, rec.a, 0) returning option_id into oa;
        insert into public.options (question_id, option_text, position) values (qid, rec.b, 1) returning option_id into ob;

        -- turnout is skewed: most decisions get a handful of votes, a few go big
        nvoters := least(6 + floor(70 * power(random(), 2.2))::int, array_length(uids, 1) - 1);
        share := 18 + random() * 64;
        insert into public.votes (question_id, option_id, user_id, created_at)
        select qid, case when random() * 100 < share then oa else ob end, v.user_id,
               created + random() * (least(now(), closes) - created)
        from (select x as user_id from unnest(uids) x where x <> author order by random() limit nvoters) v;

        -- arguments on about half the decisions, written for the side the voter picked
        if random() < 0.5 then
          insert into public.arguments (question_id, option_id, user_id, body, convincing_count, created_at)
          select qid, v.option_id, v.user_id,
                 replace(arg_templates[1 + floor(random() * array_length(arg_templates, 1))::int], '{label}',
                         case when v.option_id = oa then rec.a else rec.b end),
                 floor(random() * power(random() * 4, 2))::int, v.created_at + interval '7 minutes'
          from public.votes v where v.question_id = qid order by random() limit 1 + floor(random() * 4)::int;
        end if;
      end loop;
    end loop;
  end loop;

  -- some closed decisions have a reported outcome
  update public.questions q set outcome_option_id = (select option_id from public.options o where o.question_id = q.question_id order by random() limit 1),
                                outcome_at = q.closes_at + interval '3 hours'
  where q.closes_at < now() and q.user_id = any(uids) and random() < 0.5;

  update public.options o set votes_count = (select count(*) from public.votes v where v.option_id = o.option_id);
  update public.questions q set votes_total = (select count(*) from public.votes v where v.question_id = q.question_id),
                                args_count = (select count(*) from public.arguments a where a.question_id = q.question_id);
end
$seed$;
